Thread t = new Thread(() -> System.out.println("A"));
t.start();   // asks the JVM for a NEW thread, which runs the task
// t.run();  // just a normal method call: still ONE thread!
t.join();    // wait here until t has finished
System.out.println("B");   // always after A

synchronized String take() throws InterruptedException {
    while (items.isEmpty()) {   // WHILE, never IF
        wait();
    }
    return items.removeFirst();
}

int old, next;
do {
    old = value.get();          // read
    next = old + 1;             // compute
} while (!value.compareAndSet(old, next)); // retry if it changed

async function sequential() {
	await sleep(300);
	await sleep(200);
	await sleep(100);          // total about 600 ms
}
async function together() {
	await Promise.all([sleep(300), sleep(200), sleep(100)]); // about 300 ms
}

console.log("A");
setTimeout(() => console.log("B"), 0);        // macrotask
Promise.resolve().then(() => console.log("C")); // microtask
(async () => { console.log("D"); await null; console.log("E"); })();
console.log("F");
// prints: A D F C E B
